user_guide<-function(upload_mb){
 tagList(
  div(class='guide-hero',span(class='eyebrow','開始使用 EPIQUANTA'),h1('四個步驟，完成研究分析。'),p('先匯入資料，再依研究設計與資料結構選擇方法。完成分析後，從結果旁下載表格與圖形。'),actionButton('guide_start','開始匯入資料 →',class='btn-primary')),
  div(class='guide-grid',
   div(class='guide-step',span(class='guide-number','01'),h3('匯入資料'),p('在左側選擇檔案來源、編碼與缺失標記，按「送出資料 →」。'),tags$ul(tags$li('檔案超過上傳上限時，請選「本機大檔」。')),p(class='guide-tip','第一次操作可先使用合成示範資料。')),
   div(class='guide-step',span(class='guide-number','02'),h3('確認變項與研究設計'),p('到「資料與變項」檢查自動辨識結果。需要調整時，按欄位旁的「修改」，設定型態、類別次序或參考組後儲存。'),p('再於左側依序選擇「研究設計」與「資料結構」。欄位很多時，可用搜尋、型態篩選及分頁找到變項。')),
   div(class='guide-step',span(class='guide-number','03'),h3('選擇方法並執行'),p('選擇分析目的與分析方式，再指定結果、事件組、預測變項及所需欄位。勾選要納入的干擾因子，可用「全選／清除」調整。'),p('完成設定後按「送出並執行分析」。Bootstrap 或因素分析可能需要較長時間，可從進度提示確認狀態。')),
   div(class='guide-step',span(class='guide-number','04'),h3('查看結果與下載'),p('「分析結果」上方提供 R 版本、套件版本與計算邏輯。每份表格旁可下載 Word／Excel；圖形旁可下載 PNG／PDF。'),p('修改設定後請重新執行。下載沒有反應時，可展開「儲存到本機」，完成後會顯示檔案位置。'))
  ),
  div(class='card guide-faq',h3('依資料安排分析'),
   tags$details(tags$summary('如何選擇資料結構？'),tags$ul(tags$li('獨立個案：每人一筆，個案之間沒有配對或群聚關係。'),tags$li('配對／匹配：有配對組 ID；兩條件比較另需條件欄。配對病例對照可選條件式 Logistic。'),tags$li('重複測量：整理成長格式，每列一次訪視；準備個案 ID、時間／訪視與結果欄，再選 GEE、混合模型或兩次配對比較。'),tags$li('群聚資料：每人一筆，另有醫院、學校等單一層級群聚 ID。'),tags$li('複雜抽樣：準備資料提供者指定的分析權重、PSU 與分層欄位；需要子母體時，在分析設定內選擇。'),tags$li('復發事件：準備每個風險區間的 start、stop、事件指標及個案 ID。'))),
   tags$details(tags$summary('大檔案如何讀取？'),tags$ol(tags$li('選「本機大檔（免上傳）」，貼上檔案完整路徑。'),tags$li('按「讀取欄名與檔案資訊」，搜尋並勾選研究需要的欄位。'),tags$li('按「送出資料 →」，讀取所選欄位的全部資料列。')),p('CSV／TSV 可跳過未選欄位；Excel 仍需讀取活頁簿。資料與模型計算會使用記憶體，匯入成功不表示所有大型模型都能在目前電腦完成。')),
   tags$details(tags$summary('一般中介的 X 是連續變項，如何設定？'),p('選擇 X 後，預設估計每增加 1 個原始單位的效果；可改為 10 或其他正數，不需填 a0、a1。若需比較兩個特定數值，改選「指定兩個數值比較」再填 a0、a1。X 會保持連續，不會切成兩組。結果及匯出表會標示效果單位。因果中介仍需明確指定 a0、a1。')),
   tags$details(tags$summary('信度、EFA、CFA、SEM 與中介在哪裡？'),p('信度、EFA、CFA：選「量表品質與效度」。一般中介、因果中介、SEM：選「路徑與機制分析」，再選對應分析方式。可選方法會依研究設計與資料結構調整。'),p('SEM 先在「構面與路徑」的「終點結果 Y」選結果欄位與型態；二元結果需指定事件組，潛在結果則在該區選題。接著新增其他構面、選題並逐條連接到 Y；進階模式可輸入 lavaan 語法。EFA 可用「＋新增構面」分開選擇各題組。CFA 與信度可按「＋新增構面」，在每張卡片直接搜尋選題；CFA 依已確認題型自動選 MLR／WLSMV，也可改用進階語法。信度的反向題只列已選題項，選取後再填理論量尺上下界。CFA 可選分構面檢查或聯合驗證；分構面不提供聯合區辨效度。SEM 會帶入已確認的順序題與 Y 設定，順序模型請選 WLSMV；「補充順序題設定」僅列出模型中仍需設定的欄位。反向題須填入量尺的理論最低與最高分。')),
   tags$details(tags$summary('重複測量的描述表如何閱讀？'),p('目前普通描述表以觀測列摘要：同一人的多次訪視會各計一筆。合併平均不是先算每人平均，也不會自動只取基線。若按訪視分組，表格呈現各時間點的觀測分布；時間或組間差異推論請使用 GEE、混合模型或配對方法。')),
   tags$details(tags$summary('下次如何啟動？'),p('將下載的程式壓縮檔完整解壓縮。每次使用時雙擊資料夾內的 Start_Epiquanta.cmd；依啟動提示開啟網頁。分析結束後按右上角「關閉本機服務」。'),p('若網頁無法連線，先確認本機服務已啟動；只有重新整理網址不會啟動 R 服務。'))
  )
 )
}
